insert into public.video_topic_slices (course_code, topic_id, sort_order, unit, group_topic, source, explainer, explainer_url, lab, lab_url, slice, video_topic, problem)
select t->>'c', t->>'id', (t->>'o')::int, t->>'u', t->>'g', t->>'s', t->>'e', t->>'eu', t->>'l', t->>'lu', (x->>0)::int, x->>1, x->>2
from jsonb_array_elements($j$[{"c":"PHCH 4112","id":"4112-P1","o":1,"u":"U1 Matter and Measurements (Pt.1)","g":"Classifying matter","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"States of matter","Classify 5 pharmacy items (e.g. oxygen, syrup, tablet) by state and explain the particle arrangement."],[2,"Elements, compounds and mixtures","Classify oxygen, water, sodium chloride, normal saline and air. Give a reason for each."],[3,"Homogeneous vs heterogeneous mixtures","Classify a syrup, a suspension and an emulsion. Explain why a suspension must be shaken."],[4,"Physical vs chemical change","Sort four changes (dissolving sugar, an effervescent tablet fizzing, ice melting, iron rusting)."],[5,"Separation techniques","Choose and order the methods to recover salt and sand from a salt–sand–water mixture."]]},{"c":"PHCH 4112","id":"4112-P2","o":2,"u":"U1 Matter and Measurements (Pt.2)","g":"Measurement","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"SI base and derived units","Convert 250 mg to g and 5 mL to L, then name the SI base unit for each quantity."],[2,"Choosing a measuring instrument","Choose the instrument to measure exactly 10.00 mL, 500 mg and 37 °C. Explain each choice."],[3,"Significant figures","Report 12.0 g ÷ 3.0 mL to the correct number of significant figures."],[4,"Accuracy, precision and % error","Judge four sets of tablet weights against a 500 mg target and calculate one % error."],[5,"Solubility calculations","A drug dissolves 3.6 g in 10 mL water. Express its solubility in g/100 mL."]]},{"c":"PHCH 4112","id":"4112-A","o":3,"u":"U2 Atomic Structure (Pt.1)","g":"Atomic theory and electron configuration","s":"Explainer + free-play lab","e":"Atomic Structure Explorer","eu":"labs/atomic-structure.html","l":"Atomic Orbital Lab (Learn)","lu":"labs/orbitals.html","x":[[1,"Atomic theory","State Dalton's postulates. Explain which postulate isotopes break."],[2,"Bohr's model","Explain why an electron falling from n = 3 to n = 2 gives out light."],[3,"Protons, neutrons, electrons","Work out the protons, neutrons and electrons in ²³Na and in Na⁺."],[4,"Aufbau principle","Write the ground-state configuration of Na (Z = 11) and K (Z = 19) in filling order."],[5,"Pauli principle and Hund's rule","Draw the orbital boxes for N and O. Explain where each rule applies."]]},{"c":"PHCH 4112","id":"4112-B","o":4,"u":"U2 Atomic Structure (Pt.2)","g":"Orbitals and quantum numbers","s":"Explainer + free-play lab","e":"Atomic Orbital Lab","eu":"labs/orbitals.html","l":"Atomic Orbital Lab (Explore)","lu":null,"x":[[1,"Shapes of s, p and d orbitals","Show a 2p and a 3d orbital in the lab and describe how their shapes differ."],[2,"The four quantum numbers","State what n, l, mₗ and mₛ each describe."],[3,"Designating an electron","Give the four quantum numbers of the outermost electron of Na."],[4,"Configuration and the periodic table","From the configuration of Cl, work out its period, group and block."],[5,"Orbital size and nodes","Compare 1s, 2s and 3s in the lab. Explain why 3s is the largest."]]},{"c":"PHCH 4112","id":"4112-C","o":5,"u":"U2 Atomic Structure (Pt.2)","g":"Periodic trends","s":"Explainer + free-play lab","e":"Periodic Trends Explainer","eu":"labs/periodic-trends/index.html","l":"Periodic Trends Lab","lu":"labs/trends.html","x":[[1,"Effective nuclear charge","Explain why Na is larger than Cl although Cl has more protons."],[2,"Atomic radius","Rank Li, Na, K and then Na, Mg, Cl by size. Explain both orders."],[3,"Ionic radius","Compare the size of Na with Na⁺ and Cl with Cl⁻. Explain both changes."],[4,"Ionisation energy","Explain why the first ionisation energy dips from Mg to Al."],[5,"Electronegativity","Rank C, N, O, F by electronegativity and predict the most polar bond with H."]]},{"c":"PHCH 4112","id":"4112-D","o":6,"u":"U3 Stoichiometry","g":"The mole and chemical equations","s":"Explainer + bench","e":"Mole and Stoichiometry Explainer","eu":"labs/stoichiometry/index.html","l":"Reaction Bench","lu":"labs/stoichiometry/lab.html","x":[[1,"The mole","How many molecules are in 0.25 mol of water?"],[2,"Molar mass","Calculate the molar mass of calcium carbonate from the periodic table."],[3,"Grams, moles and particles","How many moles of CaCO₃ are in one 1.25 g tablet?"],[4,"Types of reaction","Classify three reactions, including an antacid neutralising stomach acid."],[5,"Balancing equations","Balance Al(OH)₃ + HCl → AlCl₃ + H₂O on your own Reaction Bench round."]]},{"c":"PHCH 4112","id":"4112-E","o":7,"u":"U3 Stoichiometry","g":"Stoichiometry calculations","s":"Explainer + bench","e":"Mole and Stoichiometry Explainer","eu":"labs/stoichiometry/index.html","l":"Reaction Bench","lu":"labs/stoichiometry/lab.html","x":[[1,"Mole ratios","Read every mole ratio from one balanced equation on your Reaction Bench round."],[2,"Grams to grams","Using your own bench values, work out the mass of HCl one antacid tablet neutralises."],[3,"Limiting reagent","Using your own bench values, find the limiting reagent and show the four steps."],[4,"Excess reagent","Using your own bench values, work out how much of the excess reagent is left."],[5,"Percentage yield","Using your own bench values, calculate the percentage yield and give one reason it is below 100%."]]},{"c":"PHCH 4112","id":"4112-F","o":8,"u":"U4 Chemical Bonding (Pt.1)","g":"Bond formation and bonding theories","s":"Explainer + bench","e":"Chemical Bonding Explainer","eu":"labs/chemical-bonding/index.html","l":"Molecule Bench","lu":"labs/chemical-bonding/lab.html","x":[[1,"Why bonds form","Use the energy curve to explain why H₂ has a fixed bond length."],[2,"Ionic vs covalent","Show how Na and Cl form NaCl, and how two Cl atoms form Cl₂."],[3,"Lewis structures","Draw the Lewis structure of NH₃ in five steps, then check it on the Molecule Bench."],[4,"Octet exceptions and resonance","Draw BF₃ and explain why its boron atom breaks the octet rule."],[5,"σ and π bonds, hybridisation","State the hybridisation of carbon in CH₄ and in formaldehyde (H₂CO) and count σ and π bonds."]]},{"c":"PHCH 4112","id":"4112-G","o":9,"u":"U4 Chemical Bonding (Pt.2)","g":"Bond types, shape, polarity and forces","s":"Explainer + bench","e":"Chemical Bonding Explainer","eu":"labs/chemical-bonding/index.html","l":"Molecule Bench","lu":"labs/chemical-bonding/lab.html","x":[[1,"VSEPR shapes","Predict the shapes of CO₂ and CH₄ on your own Molecule Bench round."],[2,"Lone pairs and bond angles","Explain why the H–O–H angle (104.5°) is smaller than H–C–H in CH₄ (109.5°)."],[3,"Classifying bonds by electronegativity","Use electronegativity difference to classify the bonds in NaCl, HCl and Cl₂."],[4,"Molecular polarity","Explain why CCl₄ is non-polar but CHCl₃ is polar."],[5,"Intermolecular forces","Rank CH₄, HCl and H₂O by boiling point and name the strongest force in each."]]},{"c":"PHCH 4112","id":"4112-H","o":10,"u":"U5 Gases","g":"Gas laws","s":"Explainer + bench","e":"Gases Explainer","eu":"labs/gases/index.html","l":"Gas Bench","lu":"labs/gases/lab.html","x":[[1,"Pressure","Convert 1 atm to kPa and mmHg. Explain pressure as force ÷ area."],[2,"Boyle's law","Using your own Gas Bench values, work out the new volume when the pressure changes."],[3,"Charles's law","A balloon at 25 °C is warmed to 50 °C. Find its new volume (convert to kelvin first)."],[4,"Pressure law","Explain, with a calculation, why a heated aerosol can is dangerous."],[5,"Avogadro's law and STP","What volume does 0.50 mol of oxygen occupy at STP?"]]},{"c":"PHCH 4112","id":"4112-I","o":11,"u":"U5 Gases","g":"Ideal gas equation, kinetic theory and real gases","s":"Explainer + bench","e":"Gases Explainer","eu":"labs/gases/index.html","l":"Gas Bench","lu":"labs/gases/lab.html","x":[[1,"PV = nRT","Using your own Gas Bench values, work out the moles of oxygen in a cylinder."],[2,"Molar mass from gas data","Find the molar mass of an unknown gas from its mass, P, V and T, then name it."],[3,"Dalton's law","Find the pressure of dry gas collected over water at 25 °C."],[4,"Kinetic theory","State the postulates. Explain why helium moves faster than oxygen at the same temperature."],[5,"Real gases","Say which van der Waals correction matters more in a high-pressure cylinder, and why."]]},{"c":"PHCH 4112","id":"4112-P3","o":12,"u":"U6 Liquids and Solids","g":"Liquids and solids","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Types of solids","Classify NaCl, diamond, ice and copper as ionic, covalent network, molecular or metallic."],[2,"Crystal structures","Work out the number of atoms in a simple cubic, body-centred and face-centred cubic unit cell."],[3,"Intermolecular forces in liquids","Explain why water has a higher surface tension than ethanol."],[4,"Vapour pressure and boiling","Explain why diethyl ether evaporates faster than water at room temperature."],[5,"Phase diagrams","Read the phase diagram of water: what happens to ice when pressure rises at 0 °C?"]]},{"c":"PHCH 4112","id":"4112-P4","o":13,"u":"U7 Solutions","g":"Solutions","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Ideal vs real solutions","Explain why 50 mL ethanol + 50 mL water gives less than 100 mL."],[2,"Concentration","Work out the mass of NaCl needed for 100 mL of 0.9% w/v saline, then its molarity."],[3,"Colligative properties","Calculate the freezing point of a glucose solution of stated molality."],[4,"Molar mass from colligative data","Use a freezing-point depression result to find the molar mass of a solute."],[5,"Partition coefficient","Calculate P from a drug's concentration in octanol and water. Say what it means for absorption."]]},{"c":"PHCH 4112","id":"4112-J","o":14,"u":"U8 Acids and Bases (Pt.1)","g":"Acid–base theories, pH and pOH","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Arrhenius, Brønsted–Lowry and Lewis","Classify NH₃ and BF₃ under each theory."],[2,"Strong vs weak acids","Compare the pH of 0.1 M HCl and 0.1 M acetic acid. Explain the difference."],[3,"pH and pOH","Calculate the pH and pOH of 0.01 M HCl."],[4,"Ka and weak acids","Calculate the pH of 0.1 M acetic acid (Ka = 1.8 × 10⁻⁵)."],[5,"Kb and weak bases","Calculate the pH of 0.1 M ammonia (Kb = 1.8 × 10⁻⁵)."]]},{"c":"PHCH 4112","id":"4112-K","o":15,"u":"U8 Acids and Bases (Pt.2)","g":"Buffers, indicators and titrations","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Buffers","Explain how an acetate buffer resists a small amount of added acid."],[2,"Henderson–Hasselbalch","Calculate the pH of a buffer of 0.2 M acetate and 0.1 M acetic acid (pKa 4.74)."],[3,"Strong acid–strong base curve","Sketch the curve for 0.1 M HCl vs 0.1 M NaOH and read the equivalence-point pH."],[4,"Weak acid–strong base curve","Use a weak acid–strong base curve to show that pH = pKa at half-equivalence."],[5,"Choosing an indicator","Choose between methyl orange and phenolphthalein for a weak acid–strong base titration."]]},{"c":"PHCH 4123","id":"4123-P1","o":16,"u":"U1 Thermodynamics","g":"Thermodynamics","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Laws of thermodynamics","State the first and second laws with one pharmacy example each."],[2,"Exothermic vs endothermic","Explain, with ΔH, why an instant cold pack feels cold."],[3,"Entropy","Predict the sign of ΔS for ice melting and for a gas forming from a solid."],[4,"Calorimetry","Calculate q = mcΔT for a coffee-cup calorimeter result."],[5,"Thermochemical equations","Scale a given ΔH when the equation is doubled and reversed."]]},{"c":"PHCH 4123","id":"4123-P2","o":17,"u":"U2 Chemical Kinetics","g":"Chemical kinetics","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Reaction rate","Calculate an average rate from a concentration–time table."],[2,"Rate law and order","Find the order of reaction from initial-rate data."],[3,"Half-life","A drug degrades by first-order kinetics. Work out how much is left after two half-lives."],[4,"Temperature and collision theory","Explain why some medicines must be stored in the fridge."],[5,"Catalysts","Draw an energy profile with and without a catalyst and explain the difference."]]},{"c":"PHCH 4123","id":"4123-P3","o":18,"u":"U3 Chemical Equilibrium","g":"Chemical equilibrium","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Dynamic equilibrium and Kc","Write the Kc expression for N₂ + 3H₂ ⇌ 2NH₃."],[2,"Calculating Kc","Calculate Kc from given equilibrium concentrations."],[3,"Q vs K","Use Q to predict which way a reaction mixture will shift."],[4,"Le Chatelier: concentration and pressure","Predict the shift when pressure is increased in the ammonia equilibrium."],[5,"Le Chatelier: temperature and catalyst","Predict the shift when an exothermic equilibrium is heated, and what a catalyst changes."]]},{"c":"PHCH 4123","id":"4123-A","o":19,"u":"U4 Alkane and Alkene (Pt.1)","g":"Alkanes: structure and naming","s":"Explainer only","e":"Hydrocarbons Lab","eu":"labs/hydrocarbons/index.html","l":null,"lu":null,"x":[[1,"Homologous series","Write the next three members after ethane and state the general formula."],[2,"Bonds and shape","Explain why each carbon in an alkane is tetrahedral."],[3,"Structural isomers","Draw and name the three isomers of C₅H₁₂."],[4,"IUPAC naming rules","Name a branched alkane step by step using the four rules."],[5,"Classifying carbons","Label every carbon in 2-methylbutane as primary, secondary or tertiary."]]},{"c":"PHCH 4123","id":"4123-B","o":20,"u":"U4 Alkane and Alkene (Pt.2)","g":"Alkanes: properties and reactions","s":"Explainer only","e":"Hydrocarbons Lab","eu":"labs/hydrocarbons/index.html","l":null,"lu":null,"x":[[1,"Boiling point, chain length and branching","Rank pentane, 2-methylbutane and hexane by boiling point. Explain."],[2,"Non-polar and water-repelling","Explain why liquid paraffin does not mix with water and how pharmacy uses this."],[3,"Complete vs incomplete combustion","Balance the complete combustion of propane. Explain why too little oxygen is dangerous."],[4,"Free-radical halogenation","Label the initiation, propagation and termination steps for methane + chlorine."],[5,"Fractional distillation and cracking","Predict which tray a fraction comes from and write one cracking equation."]]},{"c":"PHCH 4123","id":"4123-C","o":21,"u":"U4 Alkane and Alkene (Pt.1–2)","g":"Rings and alkenes","s":"Explainer + bench","e":"Hydrocarbons Lab","eu":"labs/hydrocarbons/index.html","l":"Bromine Water Bench","lu":"labs/hydrocarbons/lab.html","x":[[1,"Cycloalkanes","Draw cyclohexane and explain why its formula is CₙH₂ₙ."],[2,"Alkenes and the C=C bond","Explain why the π bond makes alkenes react more easily than alkanes."],[3,"No rotation about C=C","Draw cis- and trans-but-2-ene and explain why they are different compounds."],[4,"Naming alkenes","Name two alkenes, giving the double bond the lowest number."],[5,"Bromine water test","On your own Bromine Water Bench round, identify which samples contain C=C and explain the colour change."]]},{"c":"PHCH 4123","id":"4123-P4","o":22,"u":"U6 Haloalkanes","g":"Haloalkanes","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Naming haloalkanes","Name three haloalkanes, including one with two different halogens."],[2,"Classifying haloalkanes","Classify three haloalkanes as primary, secondary or tertiary."],[3,"SN2 mechanism","Draw the mechanism and product for bromoethane + OH⁻."],[4,"SN1 vs SN2","Explain why 2-bromo-2-methylpropane reacts by SN1."],[5,"Elimination vs substitution","Predict the product of 2-bromopropane with ethanolic KOH."]]},{"c":"PHCH 4123","id":"4123-P5","o":23,"u":"U7 Alcohols and Phenols","g":"Alcohols and phenols","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Naming and classifying alcohols","Name and classify three alcohols as primary, secondary or tertiary."],[2,"Hydrogen bonding and properties","Explain why ethanol boils higher than propane though their masses are similar."],[3,"Preparing alcohols","Write the equation to prepare ethanol from ethene."],[4,"Oxidation of alcohols","Predict the oxidation products of a primary, a secondary and a tertiary alcohol."],[5,"Phenol acidity","Explain why phenol is more acidic than ethanol."]]},{"c":"PHCH 4123","id":"4123-P6","o":24,"u":"U8 Carbonyl Compounds","g":"Aldehydes and ketones","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Naming aldehydes and ketones","Name two aldehydes and two ketones."],[2,"Preparing carbonyls","Show how propanal and propanone are made from different alcohols."],[3,"Nucleophilic addition","Draw the mechanism of HCN adding to ethanal."],[4,"Aldehyde vs ketone tests","Predict the result of Tollens' and Fehling's tests on each."],[5,"Reduction","Predict the product when propanone is reduced with NaBH₄."]]},{"c":"PHCH 4123","id":"4123-P7","o":25,"u":"U9 Carboxylic Acids and Derivatives (Pt.1)","g":"Carboxylic acids: naming and properties","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Naming carboxylic acids","Name three carboxylic acids, including one with a substituent."],[2,"Hydrogen bonding","Explain why ethanoic acid boils higher than ethanol."],[3,"Acidity and substituent effects","Explain why chloroethanoic acid is stronger than ethanoic acid."],[4,"Carboxylate salts","Explain why a sodium salt of an acidic drug dissolves better in water."],[5,"Recognising derivatives","Find the ester and carboxylic acid groups in aspirin."]]},{"c":"PHCH 4123","id":"4123-P8","o":26,"u":"U9 Carboxylic Acids and Derivatives (Pt.2)","g":"Acid derivatives: preparation and reactions","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Reactivity order","Rank acyl chloride, anhydride, ester and amide by reactivity. Explain."],[2,"Esterification","Write the equation for making ethyl ethanoate."],[3,"Ester hydrolysis","Explain why aspirin tablets smell of vinegar when stored in damp conditions."],[4,"Amide formation","Write the equation for an acyl chloride reacting with ammonia."],[5,"Preparing acyl chlorides and anhydrides","Write the equation for preparing ethanoyl chloride with SOCl₂."]]},{"c":"PHCH 4123","id":"4123-P9","o":27,"u":"U10 Amines","g":"Amines","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Naming and classifying amines","Name and classify three amines as primary, secondary or tertiary."],[2,"Basicity","Explain why methylamine is a stronger base than ammonia."],[3,"Amine salts","Explain why many drugs are sold as hydrochloride salts."],[4,"Preparing amines","Write one route to prepare an amine from a haloalkane."],[5,"Reactions of amines","Write the reaction of an amine with an acid and with an acyl chloride."]]},{"c":"PHCH 4123","id":"4123-P10","o":28,"u":"U11 Stereochemistry","g":"Stereochemistry","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Structural vs stereoisomers","Classify two given pairs of molecules as structural isomers or stereoisomers."],[2,"Cis–trans isomerism","Decide which of two alkenes can show cis–trans isomerism."],[3,"Chiral centres","Find the chiral centre in ibuprofen."],[4,"Enantiomers and optical rotation","Explain what a racemic mixture does to plane-polarised light."],[5,"Chiral drugs","Explain why only one enantiomer of a drug may be active, using ibuprofen or thalidomide."]]},{"c":"PHIA 4312","id":"4312-P1","o":29,"u":"U1 Introduction to Instrumentation Analysis","g":"Instruments, glassware and measurement","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"QC vs QA","Sort five tasks into QC or QA and explain the difference."],[2,"Balances","Choose the balance for weighing 5 mg and 500 g of material. Explain readability."],[3,"Volumetric glassware","Choose the glassware to deliver exactly 25.00 mL and explain TC vs TD."],[4,"Grades of laboratory water","Choose the water grade for an HPLC mobile phase and for rinsing glassware."],[5,"Accuracy, precision and errors","Classify four errors (e.g. an uncalibrated balance) as systematic or random."]]},{"c":"PHIA 4312","id":"4312-A","o":30,"u":"U1 Introduction to Instrumentation Analysis","g":"Making oral solid doses","s":"Explainer only","e":"Oral Solid Doses Lab","eu":"labs/osd/index.html","l":null,"lu":null,"x":[[1,"Why oral solid doses","Give three reasons most medicines are tablets or capsules."],[2,"Excipients","Give the job of the diluent, binder, disintegrant and lubricant in a paracetamol tablet."],[3,"Granulation routes","Pick the route (wet, dry or direct compression) for a moisture-sensitive drug. Explain."],[4,"Compression and coating","Explain why some tablets are coated, with two examples."],[5,"Tablet defects","Diagnose a tablet that splits at the top (capping) and give one cause."]]},{"c":"PHIA 4312","id":"4312-C","o":31,"u":"U2 Volumetric Analysis","g":"Volumetric analysis and standardisation","s":"Explainer + free-play lab","e":"Titration & Gravimetry Lab","eu":"labs/titration.html","l":"Acid–Base Lab (Titration bench)","lu":"labs/acidbase.html","x":[[1,"Equivalence vs end point","Explain the difference using a titration you run in the lab."],[2,"Molarity and standard solutions","Calculate the mass of KHP needed for 250 mL of 0.1 M solution."],[3,"Primary vs secondary standards","Explain why NaOH cannot be a primary standard."],[4,"Standardising an alkali","Calculate the molarity of NaOH from a KHP titre."],[5,"Endpoint detection","Choose an indicator for HCl vs NaOH and show the endpoint in the lab."]]},{"c":"PHIA 4312","id":"4312-D","o":32,"u":"U3 Chemical Analysis","g":"Titrimetric and gravimetric methods","s":"Explainer + free-play lab","e":"Titration & Gravimetry Lab","eu":"labs/titration.html","l":null,"lu":null,"x":[[1,"Precipitation titration","Choose Mohr, Volhard or Fajans for chloride in an acidic sample. Explain."],[2,"Non-aqueous titration","Explain why a weak-base drug is titrated with perchloric acid in glacial acetic acid."],[3,"Complexometric (EDTA) titration","Calculate the calcium content of a tablet from an EDTA titre."],[4,"Redox titration","Explain why permanganate needs no indicator and calculate one result."],[5,"Gravimetric analysis","Calculate % sulfate from a BaSO₄ precipitate mass and explain occlusion."]]},{"c":"PHIA 4312","id":"4312-B","o":33,"u":"U4 Physico-Chemical Methods","g":"Tablet QC tests","s":"Explainer only","e":"Oral Solid Doses Lab","eu":"labs/osd/index.html","l":null,"lu":null,"x":[[1,"Uniformity of weight","Decide pass or fail for 20 tablet weights against the pharmacopoeial limits."],[2,"Content uniformity","Explain why the same weight does not mean the same dose, and what the acceptance value decides."],[3,"Friability","Calculate % weight loss and decide pass or fail (limit 1%)."],[4,"Disintegration","Explain why an enteric-coated tablet must pass two opposite tests."],[5,"Dissolution","Decide which dissolution stage a batch reaches from given results."]]},{"c":"PHIA 4312","id":"4312-P2","o":34,"u":"U4 Physico-Chemical Methods","g":"Other physico-chemical tests","s":"Placeholder (from TLO; no explainer yet)","e":null,"eu":null,"l":null,"lu":null,"x":[[1,"Melting point","Explain how a lower, wider melting range shows an impure sample."],[2,"Optical rotation","Calculate specific rotation from an observed rotation, path length and concentration."],[3,"Specific gravity","Calculate the specific gravity of a syrup from its mass and volume."],[4,"pH measurement","Explain how and why a pH meter is calibrated with two buffers."],[5,"Loss on drying","Calculate % loss on drying and decide pass or fail against a limit."]]},{"c":"PHIA 4312","id":"4312-E","o":35,"u":"U5 Methods of Chromatography","g":"Separation principle and extraction","s":"Explainer + bench","e":"Chromatography Explainer","eu":"labs/chromatography/index.html","l":"TLC Bench (sample prep)","lu":"labs/chromatography/tlc-lab.html","x":[[1,"How separation works","Explain stick, let go, move on, using two compounds of different polarity."],[2,"Like sticks to like","Predict which of two compounds moves further on silica, and why."],[3,"Liquid–liquid extraction","Explain why two liquids that do not mix can pull a drug out of a sample."],[4,"pH moves the drug","Choose the pH to extract basic chlorpheniramine into the organic layer."],[5,"Solid-phase extraction","Put the SPE steps in order and give one reason labs prefer SPE."]]},{"c":"PHIA 4312","id":"4312-F","o":36,"u":"U5 Methods of Chromatography","g":"Thin layer chromatography","s":"Explainer + bench","e":"Chromatography Explainer","eu":"labs/chromatography/index.html","l":"TLC Bench","lu":"labs/chromatography/tlc-lab.html","x":[[1,"Plate, tank and capillary action","Show how your own TLC Bench plate is set up and run."],[2,"Mobile phase competition","Explain how changing the mobile phase in your TLC Bench round moved the spots."],[3,"Seeing colourless spots","Explain how UV light shows spots on the plate."],[4,"Rf values","Calculate Rf from your own TLC Bench plate."],[5,"Identity and limit test","Decide pass or fail on your own TLC Bench round (identity and impurity spot)."]]},{"c":"PHIA 4312","id":"4312-G","o":37,"u":"U5 Methods of Chromatography","g":"HPLC and GC","s":"Explainer + bench","e":"Chromatography Explainer","eu":"labs/chromatography/index.html","l":"HPLC Bench","lu":"labs/chromatography/hplc-lab.html","x":[[1,"Reversed-phase HPLC","Predict the elution order of a polar and a non-polar compound on C18."],[2,"Mobile phase strength","On your HPLC Bench round, predict and show what more methanol does to the peak."],[3,"Retention time and peak area","Using your own HPLC Bench values, turn the result into % of label claim."],[4,"System suitability","Explain why the system is checked before results are trusted, using your bench limits."],[5,"GC and residual solvents","Explain how GC checks that chloroform does not stay in a tablet (explainer only)."]]},{"c":"PHIA 4312","id":"4312-H","o":38,"u":"U6 Spectroscopy and Spectrophotometry","g":"UV/Visible spectroscopy","s":"Explainer + bench","e":"Spectroscopy Explainer","eu":"labs/spectroscopy/index.html","l":"UV Bench","lu":"labs/spectroscopy/uv-lab.html","x":[[1,"Wavelength and energy","Explain why UV light lifts electrons but IR only shakes bonds."],[2,"Chromophores and pH","Explain why a drug's λmax can move when pH changes."],[3,"Measuring at λmax","On your UV Bench round, find λmax and explain why you measure there."],[4,"Beer–Lambert law","Using your own UV Bench values, calculate the concentration from absorbance."],[5,"Dissolution by UV","Using your own UV Bench values, calculate % dissolved and decide pass or fail."]]},{"c":"PHIA 4312","id":"4312-I","o":39,"u":"U6 Spectroscopy and Spectrophotometry","g":"IR/FTIR spectroscopy","s":"Explainer + bench","e":"Spectroscopy Explainer","eu":"labs/spectroscopy/index.html","l":"IR Bench","lu":"labs/spectroscopy/ir-lab.html","x":[[1,"Wavenumber","Explain why O–H appears at a higher wavenumber than C–O."],[2,"Dipole rule","Explain why a symmetric bond gives no IR band."],[3,"Functional-group and fingerprint regions","Name the bands you see in the functional-group region of your IR Bench spectrum."],[4,"Sample preparation","Choose KBr disc or ATR for a tablet powder and explain what a bad disc does."],[5,"Identity match","On your IR Bench round, decide whether the sample is chlorpheniramine and justify it."]]},{"c":"PHIA 4312","id":"4312-J","o":40,"u":"U7 Reference Standard Procedures","g":"Reference standards","s":"Explainer + bench","e":"Reference Standards and GLP Explainer","eu":"labs/qc-practice/index.html","l":"QC Lab Day","lu":"labs/qc-practice/lab.html","x":[[1,"What a reference standard is","Explain the job of a reference standard in one assay."],[2,"Primary vs secondary standards","Explain the difference between an official and a working standard."],[3,"Sources","Explain where BP, USP and EP reference standards come from and how far you trust them."],[4,"Label and certificate of analysis","Read a standard's label and certificate and say what you must check before use."],[5,"Storage and handling","On your QC Lab Day round, say what to do before opening the vial, and why."]]},{"c":"PHIA 4312","id":"4312-K","o":41,"u":"U8 Good Laboratory Procedures","g":"GLP and documentation","s":"Explainer + bench","e":"Reference Standards and GLP Explainer","eu":"labs/qc-practice/index.html","l":"QC Lab Day","lu":"labs/qc-practice/lab.html","x":[[1,"What GLP covers","Name the ten areas a GLP facility controls and explain one."],[2,"Quality assurance unit","Explain why the QA unit must be independent of the work it checks."],[3,"Equipment","Explain what calibrated, maintained and labelled means for a balance."],[4,"ALCOA+","On your QC Lab Day round, mark the record entries that break the rules and name the principle."],[5,"Correcting an entry","Show the correct way to correct a wrong entry, and why."]]},{"c":"PHIA 4312","id":"4312-L","o":42,"u":"U8 Good Laboratory Procedures","g":"Lab safety and technique","s":"Explainer + bench","e":"Reference Standards and GLP Explainer","eu":"labs/qc-practice/index.html","l":"QC Lab Day","lu":"labs/qc-practice/lab.html","x":[[1,"Hazard vs risk","Explain the difference using one QC lab solvent."],[2,"GHS labels and SDS","Read a GHS label and find the four SDS sections you use most."],[3,"Hierarchy of controls","Rank the controls for a toxic solvent and explain why PPE comes last."],[4,"Weighing by difference and minimum weight","Using your own QC Lab Day values, decide whether the weight is allowed."],[5,"Preparing a solution","Usin